class Solution { public: vector<int> twoOutOfThree(vector<int>& nums1,vector<int>& nums2,vector<int>& nums3){int mask[101]={};vector<vector<int>*> arrays={&nums1,&nums2,&nums3};for(int index=0;index<3;++index)for(int value:*arrays[index])mask[value]|=1<<index;vector<int> answer;for(int value=1;value<=100;++value)if(__builtin_popcount((unsigned)mask[value])>=2)answer.push_back(value);return answer;} };
